const originalColor = 'rgb(204,217,0)';
export function coloredPendingIcon(hue) {
    const svg = atob(pendingIconUrl.split(',')[1])
        .replace(originalColor, `hsl(${hue},75%,85%)`)
        .replace(originalColor, `hsl(${hue},75%,15%)`)
        .split('fill-opacity:0.75').join('fill-opacity:1');
    return 'data:image/svg+xml,' + encodeURIComponent(svg);
}
